import React, { useState } from 'react';
import Dashboard from './components/Dashboard';
import Students from './components/Students';
import AIQuery from './components/AIQuery';
import Upload from './components/Upload';
import Validation from './components/Validation';
import SchemaView from './components/SchemaView';
import Login from './components/Login';

const NAV = [
  { id: 'dashboard', label: '📊 Dashboard' },
  { id: 'students', label: '🎓 Students' },
  { id: 'query', label: '🤖 AI Query' },
  { id: 'upload', label: '📁 Upload' },
  { id: 'validation', label: '⚠️ Validation' },
  { id: 'schema', label: '🗄️ Schema' },
];

export default function App() {
  const [page, setPage] = useState('dashboard');
  const [authed, setAuthed] = useState(!!sessionStorage.getItem('auth'));

  const handleLogout = () => {
    sessionStorage.removeItem('auth');
    setAuthed(false);
  };

  if (!authed) return <Login onLogin={() => setAuthed(true)} />;

  const renderPage = () => {
    switch (page) {
      case 'dashboard': return <Dashboard />;
      case 'students': return <Students />;
      case 'query': return <AIQuery />;
      case 'upload': return <Upload />;
      case 'validation': return <Validation />;
      case 'schema': return <SchemaView />;
      default: return <Dashboard />;
    }
  };

  return (
    <div className="app">
      <aside className="sidebar">
        <div className="sidebar-logo">🎓 Student DBMS</div>
        <nav>
          {NAV.map(n => (
            <button key={n.id} className={page === n.id ? 'active' : ''} onClick={() => setPage(n.id)}>
              {n.label}
            </button>
          ))}
        </nav>
        <div style={{ padding: '12px 16px', borderTop: '1px solid #2d2d4e' }}>
          <button onClick={handleLogout}
            style={{ width: '100%', padding: '10px', background: '#e53935', border: 'none',
              borderRadius: 8, color: '#fff', cursor: 'pointer', fontSize: '0.85rem' }}>
            🚪 Logout
          </button>
        </div>
      </aside>
      <div className="main">
        <div className="topbar">
          <h1>AI-Powered Student Data Management System</h1>
          <span style={{ fontSize: '0.8rem', color: '#666' }}>MySQL · FastAPI · React · 👤 admin</span>
        </div>
        <div className="content">{renderPage()}</div>
      </div>
    </div>
  );
}
